package dev.navifold.player;
import org.junit.Test;import org.json.*;import java.util.*;import static org.junit.Assert.*;
public class MusicProfileTest {
 JSONObject track()throws Exception{return new JSONObject().put("id","private-id").put("title","Song").put("artist","Artist").put("album","Album");}
 String response(){return "[{\"id\":0,\"moods\":[\"calm\",\"focus\"],\"energy\":25,\"instrumental\":\"unknown\",\"confidence\":80}]";}
 @Test public void profilesImproveSparseTagAffinityButNotFlowPermissions()throws Exception{JSONObject a=track().put("aiConfidence",80).put("aiMoods",new JSONArray().put("calm")).put("aiEnergy",25),b=track().put("id","another").put("aiConfidence",80).put("aiMoods",new JSONArray().put("calm")).put("aiEnergy",25);double ranked=SmartLibrary.affinity(a,b);b.remove("aiMoods");b.remove("aiEnergy");b.remove("aiConfidence");assertTrue(ranked>SmartLibrary.affinity(a,b));a.put("genre","Pop");b.put("genre","J-pop");assertFalse(FlowPolicy.allows(a,b,1));}
 @Test public void cacheIsValidUntilMetadataChanges()throws Exception{JSONObject t=track(),p=MusicProfile.parse(response(),1).get(0);String fp=MusicProfile.fingerprint(t);assertTrue(MusicProfile.fresh(t,fp,p.toString(),System.currentTimeMillis()));t.put("title","Changed");assertFalse(MusicProfile.fresh(t,fp,p.toString(),System.currentTimeMillis()));}
 @Test public void originalGenreIsNeverOverwritten()throws Exception{JSONObject t=track().put("genre","Pop"),p=MusicProfile.parse(response(),1).get(0);JSONObject merged=MusicProfile.attach(t,MusicProfile.fingerprint(t),p.toString(),System.currentTimeMillis());assertEquals("Pop",merged.getString("genre"));assertEquals("calm",merged.getJSONArray("aiMoods").getString(0));}
 @Test public void cachedMoodLetsTaglessSongsMatch()throws Exception{JSONObject t=track(),p=MusicProfile.parse(response(),1).get(0);JSONObject enriched=MusicProfile.attach(t,MusicProfile.fingerprint(t),p.toString(),System.currentTimeMillis());assertTrue(MoodIntent.local("공부 차분한 음악").score(enriched)>0);assertEquals(0,MoodIntent.local("공부 차분한 음악").score(t),0);}
 @Test public void lowConfidenceIsNotUsedAsEvidence()throws Exception{JSONObject p=MusicProfile.parse(response(),1).get(0).put("confidence",10),t=track();JSONObject enriched=MusicProfile.attach(t,MusicProfile.fingerprint(t),p.toString(),System.currentTimeMillis());assertEquals(0,MoodIntent.local("차분").score(enriched),0);}
 @Test public void cacheExpiryAndUnknownExpiryDiffer()throws Exception{JSONObject t=track(),p=MusicProfile.parse(response(),1).get(0);long old=System.currentTimeMillis()-3L*86400000;assertTrue(MusicProfile.fresh(t,MusicProfile.fingerprint(t),p.toString(),old));p.put("confidence",0);assertFalse(MusicProfile.fresh(t,MusicProfile.fingerprint(t),p.toString(),old));}
 @Test public void obsoleteInferenceIsRemovedFromPlaybackMetadata()throws Exception{JSONObject t=track().put("aiMoods",new JSONArray().put("calm"));assertFalse(MusicProfile.attach(t,"old","{}",0).has("aiMoods"));}
 @Test public void analysisPromptContainsMetadataButNoIdsOrSecrets()throws Exception{JSONObject t=track().put("password","secret").put("path","/private/path");String prompt=MusicProfile.prompt(Collections.singletonList(t));assertTrue(prompt.contains("Song"));assertFalse(prompt.contains("private-id"));assertFalse(prompt.contains("secret"));assertFalse(prompt.contains("/private/path"));}
 @Test(expected=Exception.class) public void inventedAliasIsRejected()throws Exception{MusicProfile.parse(response().replace("\"id\":0","\"id\":9"),1);}
 @Test(expected=Exception.class) public void missingTracksAreRejected()throws Exception{MusicProfile.parse(response(),2);}
 @Test(expected=Exception.class) public void confidenceOutsideRangeIsRejected()throws Exception{MusicProfile.parse(response().replace("80","120"),1);}
}
